<script>
import NavBar from '@/components/NavBar.vue'
import DiceRoller from '../components/DiceRoller.vue'
import { marked } from 'marked'
import DOMPurify from 'dompurify'
import MobileNavBar from '../components/MobileNavBar.vue'
import Footerr from '@/components/Footerr.vue'

export default {
    data() {
        return {
            ply: null,
            edit: false,
            splitPreview: false,
            showDicePopup: false,
            saveStatus: 'Saved',
            saveTimeout: null
        }
    },
    components: {
        NavBar,
        DiceRoller,
        MobileNavBar,
        Footerr
    },
    computed: {
        hasNotes() {
            return Boolean(
                this.$md.ply &&
                this.$md.ply.stats &&
                this.$md.ply.stats.misc_notes &&
                this.$md.ply.stats.misc_notes.trim().length > 0
            );
        },
        renderedMarkdown() {
            if (!this.hasNotes) return '';
            const rawHtml = marked.parse(this.$md.ply.stats.misc_notes, {
                gfm: true,
                breaks: true
            });
            const cleanHtml = DOMPurify.sanitize(rawHtml);

            // Highlight inline D&D dice notation (e.g., 1d20+5, 2d6, d8-1) outside of HTML tags/code/links
            const dicePattern = /(<pre[\s\S]*?<\/pre>|<code[\s\S]*?<\/code>|<a[\s\S]*?<\/a>|<[^>]+>)|\b(\d*d\d+(?:\s*[+-]\s*\d+)?)\b/gi;
            return cleanHtml.replace(dicePattern, (match, ignoredBlock, diceExpr) => {
                if (ignoredBlock) return ignoredBlock;
                const normalizedRoll = diceExpr.replace(/\s+/g, '');
                return `<span class="inline-dice-roll" data-dice-roll="${normalizedRoll}" title="Click to roll ${normalizedRoll}"><i class="bi bi-dice-5-fill me-1"></i>${diceExpr}</span>`;
            });
        },
        lastRollTotal() {
            if (this.$md.diceHistory && this.$md.diceHistory.length > 0) {
                return this.$md.diceHistory[this.$md.diceHistory.length - 1].total;
            }
            return null;
        }
    },
    watch: {
        '$md.ply.stats.misc_notes'() {
            this.saveStatus = 'Saving...';
            if (this.saveTimeout) clearTimeout(this.saveTimeout);
            this.saveTimeout = setTimeout(() => {
                this.$md.savePlayer();
                this.saveStatus = 'Saved';
            }, 500);
        }
    },
    created() {
        if (!localStorage.charList) return;
        const player = JSON.parse(localStorage.charList)[this.$route.params.id];
        if (player)
            this.$md.Load.restoreFromObj(player);
        this.ply = player;
    },
    mounted() {
        if (this.$md.ply) {
            document.title = `Notes - ${this.$md.ply.name}`;
        }
        window.addEventListener('keydown', this.handleKeydown);
    },
    beforeUnmount() {
        window.removeEventListener('keydown', this.handleKeydown);
        if (this.saveTimeout) {
            clearTimeout(this.saveTimeout);
        }
        if (this.$md.ply) {
            this.$md.savePlayer();
        }
    },
    methods: {
        setEdit(value) {
            this.$md.savePlayer();
            this.saveStatus = 'Saved';
            this.edit = value;
            if (value) {
                this.$nextTick(() => {
                    this.$refs.noteEditor?.focus();
                });
            }
        },
        toggleEdit() {
            this.setEdit(!this.edit);
            return this.edit;
        },
        openDicePopup() {
            this.showDicePopup = true;
            this.$nextTick(() => {
                const input = this.$refs.dicePopupBody?.querySelector('input');
                if (input) input.focus();
            });
        },
        closeDicePopup() {
            this.showDicePopup = false;
        },
        handleKeydown(e) {
            if (e.key === 'Escape' && this.showDicePopup) {
                this.closeDicePopup();
            }
        },
        handleMarkdownClick(e) {
            const diceChip = e.target.closest('.inline-dice-roll');
            if (!diceChip) return;
            e.stopPropagation();
            const rollString = diceChip.getAttribute('data-dice-roll');
            if (rollString) {
                try {
                    const result = this.$md.Dice.x(rollString);
                    this.$md.diceHistory.push(result);
                    if (this.$md.ply) {
                        if (!this.$md.ply.dice_history) this.$md.ply.dice_history = [];
                        this.$md.ply.dice_history.push({
                            dice: result.dice,
                            compText: result.compText,
                            total: result.total,
                            max: result.max,
                            timestamp: Date.now(),
                            note: ''
                        });
                        this.$md.savePlayer();
                    }
                    this.openDicePopup();
                } catch (err) {
                    console.error('Failed to roll inline dice:', err);
                }
            }
        },
        wrapSelection(prefix, suffix, placeholder = '') {
            const textarea = this.$refs.noteEditor;
            if (!textarea) return;

            const start = textarea.selectionStart;
            const end = textarea.selectionEnd;
            const text = this.$md.ply.stats.misc_notes || '';
            const selected = text.substring(start, end) || placeholder;

            const replacement = `${prefix}${selected}${suffix}`;
            this.$md.ply.stats.misc_notes = text.substring(0, start) + replacement + text.substring(end);

            this.$nextTick(() => {
                textarea.focus();
                textarea.setSelectionRange(start + prefix.length, start + prefix.length + selected.length);
            });
        },
        insertBlockPrefix(prefix) {
            const textarea = this.$refs.noteEditor;
            if (!textarea) return;

            const start = textarea.selectionStart;
            const end = textarea.selectionEnd;
            const text = this.$md.ply.stats.misc_notes || '';

            const lineStart = text.lastIndexOf('\n', start - 1) + 1;
            this.$md.ply.stats.misc_notes = text.substring(0, lineStart) + prefix + text.substring(lineStart);

            this.$nextTick(() => {
                textarea.focus();
                textarea.setSelectionRange(start + prefix.length, end + prefix.length);
            });
        },
        insertSnippet(snippet) {
            const textarea = this.$refs.noteEditor;
            if (!textarea) return;

            const start = textarea.selectionStart;
            const text = this.$md.ply.stats.misc_notes || '';
            this.$md.ply.stats.misc_notes = text.substring(0, start) + snippet + text.substring(start);

            this.$nextTick(() => {
                textarea.focus();
                const pos = start + snippet.length;
                textarea.setSelectionRange(pos, pos);
            });
        },
        insertTable() {
            const tableSnippet = `\n| Header 1 | Header 2 | Header 3 |\n| --- | --- | --- |\n| Cell 1 | Cell 2 | Cell 3 |\n`;
            this.insertSnippet(tableSnippet);
        },
        handleEditorKeydown(e) {
            if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'b') {
                e.preventDefault();
                this.wrapSelection('**', '**', 'bold text');
            } else if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'i') {
                e.preventDefault();
                this.wrapSelection('*', '*', 'italic text');
            } else if (e.key === 'Tab') {
                e.preventDefault();
                this.insertSnippet('    ');
            }
        }
    }
}
</script>

